import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry triu_matmul_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .s32 N_param
)
{
    .reg .pred p_oob, p_lower, p_end;
    .reg .b32 rN, ri, rj, rk, tx, ty, bx, by, bdx, bdy;
    .reg .b64 A, B, C, addrA, addrB, addrC, idx64, rowOff64, tmp64;
    .reg .f32 fA, fB, acc;

    // Load parameters
    ld.param.u64 A, [A_ptr];
    ld.param.u64 B, [B_ptr];
    ld.param.u64 C, [C_ptr];
    ld.param.s32 rN, [N_param];

    // Thread/block indices
    mov.u32 tx, %tid.x;
    mov.u32 ty, %tid.y;
    mov.u32 bx, %ctaid.x;
    mov.u32 by, %ctaid.y;
    mov.u32 bdx, %ntid.x;
    mov.u32 bdy, %ntid.y;

    // Compute global row (i) and col (j)
    mad.lo.u32 rj, bx, bdx, tx;
    mad.lo.u32 ri, by, bdy, ty;

    // Bounds check
    setp.ge.u32 p_oob, ri, rN;
    @p_oob ret;
    setp.ge.u32 p_oob, rj, rN;
    @p_oob ret;

    // Compute C address: addrC = C + ((i*N + j) * 4)
    mad.wide.u32 rowOff64, ri, rN, 0;  // rowOff64 = i * N (64-bit)
    cvt.u64.u32 idx64, rj;             // idx64 = j
    add.s64 idx64, rowOff64, idx64;    // idx64 = i*N + j
    shl.b64 idx64, idx64, 2;           // * sizeof(float)
    add.s64 addrC, C, idx64;

    // If lower-triangular position, write 0 and return
    setp.lt.u32 p_lower, rj, ri;
    @!p_lower bra COMPUTE;

    mov.f32 acc, 0f00000000;
    st.global.f32 [addrC], acc;
    ret;

COMPUTE:
    // Upper-triangular position: accumulate over k in [i, j]
    mov.f32 acc, 0f00000000;
    mov.u32 rk, ri;

LOOP:
    setp.gt.u32 p_end, rk, rj;
    @p_end bra LOOP_END;

    // addrA = &A[i*N + k]
    cvt.u64.u32 idx64, rk;
    add.s64 tmp64, rowOff64, idx64; // i*N + k
    shl.b64 tmp64, tmp64, 2;
    add.s64 addrA, A, tmp64;

    // addrB = &B[k*N + j]
    mad.wide.u32 tmp64, rk, rN, 0;  // k*N
    cvt.u64.u32 idx64, rj;          // j
    add.s64 tmp64, tmp64, idx64;    // k*N + j
    shl.b64 tmp64, tmp64, 2;
    add.s64 addrB, B, tmp64;

    ld.global.f32 fA, [addrA];
    ld.global.f32 fB, [addrB];
    fma.rn.f32 acc, fA, fB, acc;

    add.u32 rk, rk, 1;
    bra LOOP;

LOOP_END:
    st.global.f32 [addrC], acc;
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        if A.dtype != torch.float32 or B.dtype != torch.float32:
            raise NotImplementedError("ModelNew supports float32 tensors only.")
        if A.dim() != 2 or B.dim() != 2 or A.shape != B.shape or A.shape[0] != A.shape[1]:
            raise ValueError("Inputs must be square matrices of the same shape.")
        if not (A.is_cuda and B.is_cuda):
            raise RuntimeError("ModelNew requires CUDA tensors for inputs.")
        if not A.is_contiguous():
            A = A.contiguous()
        if not B.is_contiguous():
            B = B.contiguous()

        N = A.shape[0]
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()
        block_x, block_y, block_z = 16, 16, 1
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y
        grid_z = 1

        module.launch(
            "triu_matmul_f32",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

